name: CI

on:
  push:
    branches: [ main ]
  pull_request:
    branches: [ main ]

jobs:
  test:
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4

    - name: Setup Dart
      uses: dart-lang/setup-dart@v1
      with:
        sdk: stable

    - name: Install dependencies
      run: |
        dart pub get
        cd examples/flutter_example && dart pub get
        cd ../dart_example && dart pub get

    - name: Verify version consistency
      run: |
        # Create version verification script
        cat > verify_version.dart << 'EOF'
        import 'dart:io';
        import 'package:yaml/yaml.dart';

        void main() {
          final marionetteMcpPubspec = File('packages/marionette_mcp/pubspec.yaml');
          final marionetteFlutterPubspec = File('packages/marionette_flutter/pubspec.yaml');

          if (!marionetteMcpPubspec.existsSync()) {
            print('Error: marionette_mcp pubspec not found');
            exit(1);
          }

          if (!marionetteFlutterPubspec.existsSync()) {
            print('Error: marionette_flutter pubspec not found');
            exit(1);
          }

          final mcpYaml = loadYaml(marionetteMcpPubspec.readAsStringSync());
          final flutterYaml = loadYaml(marionetteFlutterPubspec.readAsStringSync());

          final mcpVersion = mcpYaml['version'];
          final flutterVersion = flutterYaml['version'];

          if (mcpVersion != flutterVersion) {
            print('Error: Versions do not match - marionette_mcp: $mcpVersion, marionette_flutter: $flutterVersion');
            exit(1);
          }

          # Generate version.g.dart
          final versionFile = File('packages/marionette_mcp/lib/version.g.dart');
          versionFile.writeAsStringSync('''// Generated file - do not edit
const String marionetteMcpVersion = '$mcpVersion';
''');

          print('Versions verified and version.g.dart generated successfully');
        }
        EOF

        # Run the script
        dart verify_version.dart

    - name: Check for modified version.g.dart
      run: |
        git diff --exit-code || (echo "Error: version.g.dart was modified during build" && exit 1)

    - name: Run tests
      run: |
        dart test
        cd examples/flutter_example && dart test
        cd ../dart_example && dart test

    - name: Run code analysis
      run: |
        dart analyze
        cd examples/flutter_example && dart analyze
        cd ../dart_example && dart analyze

    - name: Run security checks
      run: |
        dart pub global activate dart_code_metrics
        dart pub global run dart_code_metrics:analyze lib --reporter=checkstyle > metrics.xml || true
        dart pub global deactivate dart_code_metrics

    - name: Validate pubspec.yaml files
      run: |
        dart pub get --offline
        cd examples/flutter_example && dart pub get --offline
        cd ../dart_example && dart pub get --offline

    - name: Restore original example paths
      run: |
        # Ensure example pubspecs have correct paths
        sed -i 's|path: ../../packages/marionette_flutter|path: ../../packages/marionette_flutter|g' examples/flutter_example/pubspec.yaml
        sed -i 's|path: ../../packages/marionette_flutter|path: ../../packages/marionette_flutter|g' examples/dart_example/pubspec.yaml
